    align-items: flex-start;
    justify-content: center;
    padding: calc(24px + var(--sat, 0px)) 16px calc(24px + var(--sab, 0px));
    background: linear-gradient(180deg, #f7f7f5 0%, #efefec 100%);
    overflow-y: auto;
}
.auth-card {
    width: 100%;
    max-width: 380px;
    margin: auto 0;
    background: #ffffff;
