    font-weight: 800;
    letter-spacing: -1px;
    color: #1d1d1f;
}
.auth-tagline {
    margin-top: 4px;
    font-size: 13px;
    color: #85858a;
}
.auth-tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4px;
    background: #ececea;
    border-radius: 999px;
    padding: 4px;
    margin: 8px 0 2px;
}
.auth-tabs button {
    border: 0;
