    width: 100%;
    padding: 12px 14px;
    border: 1px solid var(--separator, #e5e5e5);
    border-radius: 12px;
    background: #fbfbfa;
    font-size: 16px;
    color: #1d1d1f;
    outline: none;
    transition:
        border-color 0.12s,
        background 0.12s;
}
.auth-field > input:focus {
    border-color: #1d1d1f;
    background: #ffffff;
}
.auth-error {
    padding: 8px 12px;
    border-radius: 10px;
    background: rgba(230, 91, 91, 0.1);
    border: 1px solid rgba(230, 91, 91, 0.25);
    color: #b23636;
    font-size: 13px;
}
.auth-submit {
    margin-top: 2px;
    border: 0;
    padding: 14px 20px;
    border-radius: 999px;
    background: #1d1d1f;
    color: #fff;
    font-size: 16px;
    font-weight: 600;
    letter-spacing: 0.2px;
    transition:
        opacity 0.12s,
        transform 0.12s;
}
.auth-submit:disabled {
    opacity: 0.4;
}
.auth-submit:not(:disabled):active {
    transform: scale(0.98);
}
.auth-note {
    margin-top: 6px;
    padding: 10px 12px;
    border-radius: 10px;
    background: #f7f7f5;
    color: #73737a;
    font-size: 12px;
    line-height: 1.6;
}
.auth-version {
    text-align: center;
    font-size: 11px;
    color: #a8a8ac;
    letter-spacing: 0.4px;
