    align-items: center;
    justify-content: center;
    padding: calc(20px + var(--sat, 0px)) 16px calc(20px + var(--sab, 0px));
}
.auth-modal-backdrop {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    background: rgba(20, 20, 22, 0.45);
}
.auth-modal {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 380px;
    max-height: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
    background: #ffffff;
    border-radius: 20px;
    padding: 22px 20px 18px;
    box-shadow: 0 20px 60px #00000042;
    overflow-y: auto;
}
.auth-modal-title {
    font-size: 18px;
    font-weight: 700;
    color: #1d1d1f;
    letter-spacing: -0.3px;
}
.auth-modal-body {
