    flex-direction: column;
    gap: 10px;
}
.auth-modal-body p {
    margin: 0;
}
.auth-modal-body b {
    color: #1d1d1f;
}
.auth-modal-facts {
    display: flex;
    flex-direction: column;
    gap: 6px;
    padding: 10px 12px;
    border-radius: 12px;
