.auth-modal-facts > div {
    display: flex;
    justify-content: space-between;
    gap: 10px;
    font-size: 12.5px;
}
.auth-modal-facts span {
    color: #85858a;
    flex: 0 0 auto;
}
.auth-modal-facts b {
    color: #1d1d1f;
    text-align: right;
}
.auth-modal-ghost {
    border: 0;
    background: transparent;
    width: 100%;
    padding: 8px 0;
    color: #85858a;
    font-size: 13px;
}
@media (min-width: 640px) {
    html,
    body {
        background: #d9d9d6;
    }
    body {
        display: flex;
        justify-content: center;
        background: linear-gradient(180deg, #dad9d6 0%, #cfcecc 100%);
        min-height: 100vh;
        min-height: 100dvh;
    }
    #root {
        width: 100%;
        max-width: 480px;
        margin: 0 auto;
        background: var(--bg, #f4f4f4);
        box-shadow: 0 0 40px #0000001a;
        overflow: hidden;
        max-height: 100vh;
        max-height: 100dvh;
    }
    .auth-screen {
        max-width: 480px;
        margin: 0 auto;
        box-shadow: 0 0 40px #0000001a;
    }
