    font-family:
        Songti SC,
        "Noto Serif SC",
        serif;
    font-size: 40px;
    font-weight: 600;
    letter-spacing: 2px;
    line-height: 1.1;
}
.bio-mag-rule {
    display: block;
    width: 28px;
    height: 1px;
    margin: var(--sp-5) auto;
    background: var(--c-label);
}
.bio-mag-lead {
    margin: 0;
    max-width: 22em;
    font-family:
        Songti SC,
        "Noto Serif SC",
        serif;
    font-size: 16px;
    line-height: 1.85;
    color: var(--c-label-2);
}
.bio-mag-meta {
    margin-top: var(--sp-5);
    font-size: var(--fs-caption);
    letter-spacing: 0.3px;
    color: var(--c-label-3);
    font-variant-numeric: tabular-nums;
}
.bio-mag-toc {
    display: grid;
    margin: 0 0 var(--sp-6);
    padding: var(--sp-4) 0 var(--sp-2);
    border-top: 0.5px solid var(--c-line);
    border-bottom: 0.5px solid var(--c-line);
}
.bio-mag-toc .bio-eyebrow {
    margin-bottom: var(--sp-2);
}
.bio-mag-toc button {
    display: grid;
    grid-template-columns: 28px 1fr auto;
    align-items: baseline;
    gap: var(--sp-2);
    padding: 9px 0;
    text-align: left;
}
.bio-mag-toc button + button {
    border-top: 0.5px solid var(--c-line);
}
.bio-mag-toc em {
    font-style: normal;
    font-size: var(--fs-footnote);
    color: var(--c-label-3);
}
.bio-mag-toc b {
    font-size: var(--fs-callout);
    font-weight: var(--fw-medium);
}
.bio-mag-toc i {
    font-style: normal;
    font-size: 9.5px;
    letter-spacing: 1.6px;
    color: var(--c-label-4);
}
.bio-mag-sec {
    padding: var(--sp-6) 0 var(--sp-2);
    scroll-margin-top: 12px;
}
.bio-mag-h {
    display: flex;
    align-items: flex-end;
    gap: var(--sp-3);
    margin-bottom: var(--sp-4);
}
.bio-mag-h em {
    font-style: normal;
    font-size: 44px;
    font-weight: 200;
    line-height: 0.9;
    letter-spacing: -1px;
    color: var(--c-label);
}
.bio-mag-h span {
    display: grid;
    gap: 3px;
    padding-bottom: 3px;
}
.bio-mag-h i {
    font-style: normal;
    font-size: 9.5px;
    font-weight: var(--fw-semibold);
    letter-spacing: 2.2px;
    color: var(--c-label-3);
}
.bio-mag-h b {
    font-size: var(--fs-headline);
    font-weight: var(--fw-semibold);
    letter-spacing: 0.5px;
}
.bio-mag-sec p {
    margin: 0 0 var(--sp-3);
    font-family:
        Songti SC,
        "Noto Serif SC",
        serif;
    font-size: 16px;
    line-height: 1.95;
    text-align: justify;
    color: #222;
}
.bio-mag-sec blockquote {
    margin: 0 0 var(--sp-4);
    padding: var(--sp-1) 0 var(--sp-1) var(--sp-4);
    border-left: 1.5px solid var(--c-label);
    font-family:
        Songti SC,
        "Noto Serif SC",
        serif;
    font-size: 20px;
    line-height: 1.6;
    font-weight: 600;
    color: var(--c-label);
}
.bio-mag-sec.is-now {
    margin-top: var(--sp-4);
    padding: var(--sp-5) var(--sp-5) var(--sp-2);
    border-radius: var(--rad-lg);
    background: var(--c-fill-3);
}
.bio-mag-end {
    display: grid;
    justify-items: center;
    gap: var(--sp-4);
    padding-top: var(--sp-6);
    text-align: center;
}
.bio-mag-end .bio-mag-rule {
    margin: 0;
}
.bio-mag-end div {
    display: flex;
    gap: var(--sp-2);
}
.bio-mag-end button {
    height: 38px;
    padding: 0 var(--sp-5);
    border-radius: var(--rad-pill);
    font-size: var(--fs-subhead);
    font-weight: var(--fw-medium);
    color: var(--c-label);
    box-shadow: var(--shadow-hair);
    background: var(--c-surface);
}
.bio-mag-end button.solid {
    background: var(--c-ink);
    color: var(--c-on-ink);
    box-shadow: none;
}
.bio-mag-end p {
    margin: 0;
    max-width: 24em;
    font-size: var(--fs-footnote);
    line-height: 1.7;
    color: var(--c-label-3);
}
@media (prefers-reduced-motion: reduce) {
    .bio-cover:active {
        transform: none;
    }
}
.mem-shared-card {
    width: 100%;
    display: flex;
    align-items: center;
    gap: var(--sp-3);
    margin: 0 0 var(--sp-6);
    padding: var(--sp-4) var(--sp-4) var(--sp-4) 18px;
    border-radius: 18px;
    background: #fff;
    box-shadow: var(--shadow-card);
    text-align: left;
    color: var(--text);
    transition: transform 0.18s;
}
.mem-shared-card:active {
    transform: scale(0.985);
}
.mem-shared-card-copy {
    flex: 1;
    min-width: 0;
    display: grid;
    gap: 3px;
}
.mem-shared-card-copy small {
    font-size: 10px;
    font-weight: 650;
    letter-spacing: 0.14em;
    color: var(--text-3);
}
.mem-shared-card-copy b {
    font-size: 15px;
    font-weight: 620;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mem-shared-card-copy em {
    font-style: normal;
    font-size: 12px;
    color: var(--text-2);
    font-variant-numeric: tabular-nums;
}
.mem-shared-card-chev {
    flex: 0 0 auto;
    color: var(--text-3);
}
.mem-with-faces.lg > * + * {
    margin-left: -9px;
}
.mem-with-faces.lg > *,
.mem-with-faces.xl > * {
    box-shadow: 0 0 0 2px #fff;
}
.mem-with-faces.xl > * + * {
    margin-left: -12px;
}
.shm {
    padding: var(--sp-2) var(--sp-4) var(--sp-6);
}
.shm-picks {
    display: flex;
    gap: var(--sp-2);
    overflow-x: auto;
    margin: 0 calc(-1 * var(--sp-4)) var(--sp-4);
    padding: var(--sp-1) var(--sp-4);
    scrollbar-width: none;
}
.shm-picks::-webkit-scrollbar {
    display: none;
}
.shm-picks button {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 34px;
    padding: 0 12px 0 6px;
    border-radius: 999px;
    background: #fff;
    box-shadow: var(--shadow-hair);
    font-size: 13px;
    font-weight: 560;
    color: var(--text-2);
}
.shm-picks button em {
    font-style: normal;
    font-size: 11px;
    color: var(--text-3);
    font-variant-numeric: tabular-nums;
}
.shm-picks button.on {
    background: var(--text);
    color: var(--bg);
}
.shm-picks button.on em {
    color: var(--separator-strong);
}
.shm-head {
    display: grid;
    justify-items: center;
    gap: 6px;
    text-align: center;
    padding: var(--sp-3) 0 var(--sp-5);
}
.shm-head b {
    font-size: 18px;
    font-weight: 650;
    letter-spacing: -0.2px;
    margin-top: 4px;
}
.shm-head small {
    font-size: 12px;
    color: var(--text-3);
}
.shm-list {
    display: grid;
    gap: var(--sp-3);
}
.shm-row {
    background: #fff;
    border-radius: 18px;
    box-shadow: var(--shadow-card);
    padding: 14px var(--sp-4) 6px;
}
.shm-date {
    font-size: 10.5px;
    font-weight: 650;
    letter-spacing: 0.1em;
    color: var(--text-3);
    margin-bottom: 6px;
}
.shm-side {
    width: 100%;
    display: grid;
    gap: 4px;
    text-align: left;
    padding: 8px 0 10px;
    color: var(--text);
}
.shm-side + .shm-side {
    border-top: 0.5px solid var(--separator);
}
.shm-side:disabled {
    opacity: 1;
    cursor: default;
}
.shm-who {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 11.5px;
    font-weight: 600;
    color: var(--text-2);
}
.shm-side p {
    margin: 0;
    font-size: 14px;
    line-height: 1.6;
    color: var(--graphite);
}
.shm-side p.none {
    color: var(--text-3);
    font-size: 13px;
}
.shm-foot {
    margin: var(--sp-5) 4px 0;
    font-size: 12px;
    line-height: 1.6;
    color: var(--text-3);
}
.msg-row.fresh {
    animation: msgIn 0.36s cubic-bezier(0.32, 0.72, 0, 1) backwards;
    transform-origin: 0 100%;
}
.msg-row.out.fresh {
    transform-origin: 100% 100%;
}
@keyframes msgIn {
    0% {
        opacity: 0;
        transform: translateY(12px) scale(0.94);
    }
}
@media (prefers-reduced-motion: reduce) {
    .msg-row.fresh {
        animation: none;
    }
}
.m26-pay-layer {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 80;
    display: flex;
    align-items: flex-end;
    background: rgba(0, 0, 0, 0.32);
    animation: m26-dim 0.24s ease both;
}
.m26-pay-layer.out {
    animation: m26-dim-out 0.24s ease forwards;
}
.m26-pay-layer.out .m26-paysheet {
    animation: m26-sheet-out 0.24s cubic-bezier(0.32, 0.72, 0, 1) forwards;
}
@keyframes m26-dim {
    0% {
        background: rgba(0, 0, 0, 0);
    }
}
@keyframes m26-dim-out {
    to {
        background: rgba(0, 0, 0, 0);
    }
}
@keyframes m26-sheet-in {
    0% {
        transform: translateY(100%);
    }
}
@keyframes m26-sheet-out {
    to {
        transform: translateY(100%);
    }
}
.m26-paysheet {
    width: 100%;
    padding: 18px 20px calc(var(--sab, 0px) + 22px);
    border-radius: 28px 28px 0 0;
    background: #fff;
    color: #111;
    box-shadow: 0 0 30px #0000001f;
    animation: m26-sheet-in 0.42s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paysheet-h {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 30px;
}
.m26-paysheet-h b {
    font-size: 15px;
    font-weight: 700;
    letter-spacing: -0.2px;
}
.m26-paysheet-h button {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: #f0f0f0;
    color: #6d6d6d;
}
.m26-paysheet-amt {
    margin: 18px 0 6px;
    text-align: center;
    font-size: 40px;
    font-weight: 600;
    letter-spacing: -1px;
    font-variant-numeric: tabular-nums;
}
.m26-paysheet-rows {
    margin-top: 14px;
    border-radius: 14px;
    background: #f6f6f6;
}
.m26-paysheet-rows > div {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    padding: 13px 16px;
    font-size: 14px;
}
.m26-paysheet-rows > div + div {
    box-shadow: inset 0 0.5px #00000014;
}
.m26-paysheet-rows span {
    flex: 0 0 auto;
    color: #8a8a8a;
}
.m26-paysheet-rows b {
    min-width: 0;
    font-weight: 500;
    text-align: right;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.m26-paysheet-act {
    margin-top: 20px;
    height: 92px;
    display: flex;
    align-items: center;
    justify-content: center;
}
.m26-paysheet-act .m26-cta {
    width: 100%;
    height: 52px;
    font-size: 16px;
}
.m26-auth {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 10px;
    font-size: 13px;
    font-weight: 500;
    color: #111;
    animation: m26-fade 0.25s ease both;
}
.m26-auth svg {
    width: 56px;
    height: 56px;
}
.m26-auth svg.auth .fr {
    stroke-dasharray: 120;
    animation: m26-scan 1s ease-in-out infinite alternate;
}
.m26-auth svg.auth .fc {
    opacity: 0.9;
    animation: m26-face 1s ease-in-out infinite alternate;
}
@keyframes m26-scan {
    0% {
        opacity: 0.35;
    }
    to {
        opacity: 1;
    }
}
@keyframes m26-face {
    0% {
        transform: translateY(1px);
    }
    to {
        transform: translateY(-1px);
    }
}
.m26-ring {
    stroke-dasharray: 151;
    stroke-dashoffset: 151;
    animation: m26-draw 0.5s cubic-bezier(0.32, 0.72, 0, 1) forwards;
}
.m26-tick {
    stroke-dasharray: 34;
    stroke-dashoffset: 34;
    animation: m26-draw 0.35s 0.32s cubic-bezier(0.32, 0.72, 0, 1) forwards;
}
@keyframes m26-draw {
    to {
        stroke-dashoffset: 0;
    }
}
@keyframes m26-fade {
    0% {
        opacity: 0;
        transform: scale(0.94);
    }
}
.m26-paid {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: calc(var(--sat, 0px) + 96px) 24px 24px;
    text-align: center;
}
.m26-paid-mark {
    width: 72px;
    height: 72px;
    color: #111;
}
.m26-paid-mark svg {
    width: 100%;
    height: 100%;
}
.m26-paid h2 {
    margin: 22px 0 0;
    font-size: 22px;
    font-weight: 650;
    letter-spacing: -0.3px;
    animation: m26-rise 0.45s 0.25s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paid-amt {
    margin-top: 8px;
    font-size: 32px;
    font-weight: 600;
    letter-spacing: -0.8px;
    animation: m26-rise 0.45s 0.32s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paid p {
    margin: 8px 0 0;
    font-size: 14px;
    color: #8a8a8a;
    animation: m26-rise 0.45s 0.38s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paid-items {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 22px;
    padding: 8px 12px;
    border-radius: 14px;
    background: #f4f4f4;
    animation: m26-rise 0.45s 0.44s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paid-count {
    margin-left: 4px;
    font-size: 12.5px;
    color: #8a8a8a;
}
.m26-paid-acts {
    width: 100%;
    max-width: 340px;
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-top: 40px;
    animation: m26-rise 0.45s 0.5s cubic-bezier(0.32, 0.72, 0, 1) both;
}
.m26-paid-acts .m26-cta {
    flex: none;
    width: 100%;
    height: 50px;
}
@keyframes m26-rise {
    0% {
        opacity: 0;
        transform: translateY(10px);
    }
}
.m26-after {
    display: flex;
    justify-content: center;
    gap: 24px;
    padding: 6px 0 18px;
}
.m26-after button {
    font-size: 13px;
    color: #8a8a8a;
}
.m26-review {
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 4px 0 2px;
}
.m26-review-seg {
    display: flex;
    padding: 2px;
    border-radius: 10px;
    background: #f0f0f0;
}
.m26-review-seg button {
    flex: 1;
    height: 32px;
    border-radius: 8px;
    font-size: 13.5px;
    color: #6d6d6d;
    transition:
        background 0.2s,
        color 0.2s;
}
.m26-review-seg button.on {
    background: #fff;
    color: #111;
    font-weight: 600;
    box-shadow:
        0 0 0 0.5px #0000000a,
        0 0 8px #0000000f;
}
.m26-review textarea {
    min-height: 96px;
    padding: 12px 14px;
    border: 0;
    border-radius: 14px;
    background: #f6f6f6;
    font: inherit;
    font-size: 14px;
    resize: none;
    outline: none;
}
.m26-review .m26-cta {
    flex: none;
    width: 100%;
}
@media (prefers-reduced-motion: reduce) {
    .m26-pay-layer,
    .m26-paysheet,
    .m26-paid *,
    .m26-auth,
    .m26-ring,
    .m26-tick {
        animation: none !important;
        stroke-dashoffset: 0 !important;
    }
}
.msg-tail-badge {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 5px;
    padding: 0 2px;
    max-width: 100%;
    font-size: 11px;
    line-height: 14px;
    letter-spacing: 0.1px;
    color: #a1a1a1;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    animation: msgTailIn 0.3s ease both;
}
.msg-tail-badge.out {
    align-self: flex-end;
    justify-content: flex-end;
    text-align: right;
}
.msg-tail-badge.in {
    align-self: flex-start;
}
.msg-tail-badge b {
    font-weight: 600;
    color: #8c8c8c;
}
.msg-tail-badge i {
    flex: 0 0 auto;
    width: 3px;
    height: 3px;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.7;
}
@keyframes msgTailIn {
    0% {
        opacity: 0;
        transform: translateY(-2px);
    }
}
@media (prefers-reduced-motion: reduce) {
    .msg-tail-badge {
        animation: none;
    }
}
.tis {
    padding: var(--sp-5) var(--sheet-pad-x, 20px) var(--sheet-pad-bottom, 22px);
}
.tis-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--sp-3);
}
.tis-k {
    font-size: 9px;
    letter-spacing: 0.28em;
    text-transform: uppercase;
    color: var(--text-3);
}
.tis-title {
    margin-top: 6px;
    font-size: 21px;
    font-weight: 700;
    letter-spacing: 0.02em;
    line-height: 1.15;
    color: var(--text);
}
.tis-x {
    width: 30px;
    height: 30px;
    flex: none;
    border-radius: 50%;
    display: grid;
    place-items: center;
    background: var(--fill-2, rgba(120, 120, 120, 0.1));
    color: var(--text-2);
    transition: transform 0.16s ease;
}
.tis-x:active {
    transform: scale(0.92);
}
.tis-seg {
    position: relative;
    margin-top: var(--sp-4);
    display: grid;
    grid-template-columns: 1fr 1fr;
    padding: 3px;
    border-radius: 999px;
    background: var(--fill-2, rgba(120, 120, 120, 0.1));
}
.tis-seg-thumb {
    position: absolute;
    top: 3px;
    bottom: 3px;
    left: 3px;
    width: calc(50% - 3px);
    border-radius: 999px;
    background: var(--card, #fff);
    box-shadow: var(--shadow-card);
    transition: transform 0.3s cubic-bezier(0.32, 0.72, 0, 1);
}
.tis-seg button {
    position: relative;
    height: 32px;
    border-radius: 999px;
    font-size: 13px;
    font-weight: 600;
    letter-spacing: 0.04em;
    color: var(--text-2);
    transition: color 0.2s;
}
.tis-seg button.on {
    color: var(--text);
}
.tis-compose {
    margin-top: var(--sp-4);
    display: flex;
    gap: var(--sp-3);
    align-items: stretch;
}
.tis-thumb {
    flex: none;
    width: 76px;
    height: 76px;
    border-radius: 14px;
    overflow: hidden;
    box-shadow: var(--shadow-card);
    transform: rotate(-3deg);
    margin: 6px 2px 0 4px;
}
.tis-field {
    position: relative;
    flex: 1;
    min-width: 0;
    display: block;
    border-radius: 16px;
    background: var(--fill-2, rgba(120, 120, 120, 0.1));
}
.tis-field textarea {
    display: block;
    width: 100%;
    min-height: 118px;
    max-height: 34vh;
    padding: 12px 14px 26px;
    border: 0;
    outline: 0;
    resize: none;
    background: transparent;
    font-size: 15px;
    line-height: 1.6;
    color: var(--text);
}
.tis-field textarea::-moz-placeholder {
    color: var(--text-3);
}
.tis-field textarea::placeholder {
    color: var(--text-3);
}
.tis-count {
    position: absolute;
    right: 12px;
    bottom: 8px;
    font-size: 11px;
    color: var(--text-3);
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.04em;
    pointer-events: none;
}
.tis-note {
    margin: 10px 4px 0;
    font-size: 12px;
    line-height: 1.6;
    color: var(--text-3);
}
.tis-gen {
    margin-top: var(--sp-3);
}
.tis-actions {
    margin-top: var(--sp-5);
}
@media (prefers-reduced-motion: reduce) {
    .tis-seg-thumb {
        transition: none;
    }
}
.bgt-island {
    position: fixed;
    z-index: 1200;
