    height: 22px;
    margin-top: -9px;
    border: 0;
    border-radius: 50%;
    background: #fff;
    box-shadow:
        0 0 0 0.5px #0000000f,
        0 0 8px #00000029;
}
:where(
    input[type="range"]:not(.memory-range, .rl-range, .cts-range, .nv-rd-prog input, .cp-slider input)
)::-moz-range-thumb {
    width: 22px;
