.wx-row[data-swipe-id] {
    overflow: hidden;
    touch-action: pan-y;
}
.wx-row[data-swipe-id].in-block:active {
    background: transparent;
}
.wx-swipe-track {
    display: flex;
    align-items: center;
    gap: inherit;
    flex: 1;
    min-width: 0;
    transition: transform 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
    will-change: transform;
}
.wx-swipe-track.is-drag {
    transition: none;
}
.wx-swipe-track.is-open {
    -webkit-mask-image: linear-gradient(
        to right,
        #000 calc(100% - var(--sw-cut, 0px) - 36px),
        transparent calc(100% - var(--sw-cut, 0px))
    );
    mask-image: linear-gradient(
        to right,
        #000 calc(100% - var(--sw-cut, 0px) - 36px),
        transparent calc(100% - var(--sw-cut, 0px))
    );
}
.wx-swipe-track .wx-av {
    opacity: calc(1 - var(--sw-p, 0) * 1.6);
}
.wx-acts {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    display: flex;
    overflow: hidden;
    z-index: 1;
    transition: width 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.wx-acts.is-drag {
    transition: none;
}
.wx-act {
    flex: 1 1 0;
    min-width: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    padding: 0 2px;
    white-space: nowrap;
    overflow: hidden;
    transition: flex-grow 0.26s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.wx-act > span {
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.04em;
    overflow: hidden;
}
.wx-act > svg {
    flex: none;
}
.wx-act:active {
    filter: brightness(0.94);
}
.wx-act.act-read {
    background: #ececec;
    color: var(--ink);
}
.wx-act.act-mute {
    background: #d6d6d6;
    color: var(--ink);
}
.wx-act.act-pin {
    background: #8c8c8c;
    color: #fff;
}
.wx-act.act-del {
    background: #1c1c1c;
    color: #fff;
}
.wx-act.act-del.confirm > span {
    font-size: 13px;
    letter-spacing: 0.06em;
}
.wx-acts.is-confirm .wx-act:not(.confirm) {
    flex-grow: 0;
    padding: 0;
}
@media (prefers-reduced-motion: reduce) {
    .wx-swipe-track,
    .wx-acts,
    .wx-act {
        transition: none;
    }
}
