@keyframes apl-print {
    0% {
        transform: translateY(-102%);
    }
    15% {
        transform: translateY(-86%);
    }
    30% {
        transform: translateY(-70%);
    }
    45% {
        transform: translateY(-52%);
    }
    60% {
        transform: translateY(-34%);
    }
    75% {
        transform: translateY(-16%);
    }
    to {
        transform: translateY(0);
    }
}
@keyframes apl-fade {
    0% {
        opacity: 0;
        transform: scale(0.96);
    }
    to {
        opacity: 1;
        transform: none;
    }
}
@keyframes apl-hide {
    to {
        opacity: 0;
    }
}
@keyframes apl-show {
    to {
        opacity: 1;
    }
}
@keyframes apl-blink {
    0%,
    to {
        opacity: 0.15;
    }
    50% {
        opacity: 1;
    }
}
@keyframes apl-pulse {
    0%,
    to {
        box-shadow: 0 0 #13131559;
    }
    50% {
        box-shadow: 0 0 0 5px #13131500;
    }
}
.apl-track span.now i {
    animation-name: apl-pulse-dot;
}
@keyframes apl-pulse-dot {
    0%,
    to {
        box-shadow:
            inset 0 0 0 6px #131315,
            0 0 #13131559;
    }
    50% {
        box-shadow:
            inset 0 0 0 6px #131315,
            0 0 0 5px #13131500;
    }
}
@media (prefers-reduced-motion: reduce) {
    .apl-tk.print,
    .apl-tk.print .apl-q,
    .apl-tk.print .ld1,
    .apl-tk.print .ld2,
    .apl-pill-dot,
    .apl-track span.now i,
    .apl-tk .ld1 em,
    .apl-btn {
        animation: none !important;
        transition: none;
    }
    .apl-tk.print .ld1 {
        opacity: 0;
    }
    .apl-tk.print .ld2 {
        opacity: 1;
    }
}
