    z-index: 40;
    left: 0;
    top: 0;
    margin: 0;
    pointer-events: none;
    will-change: transform;
}
.desktop-drag-ghost-skin {
    animation: drag-pickup 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) both !important;
    transform: scale(1.055);
    opacity: 0.96;
    filter: drop-shadow(0 14px 18px rgba(0, 0, 0, 0.2));
}
.desktop-drag-ghost .widget-remove,
