    overflow: hidden;
}
.is-drop-target {
    animation: drop-target-pulse 0.46s ease-in-out infinite alternate !important;
}
.just-dropped {
    animation: drop-settle 0.3s cubic-bezier(0.22, 0.72, 0, 1) !important;
}
@keyframes drag-pickup {
    0% {
        opacity: 0.4;
        transform: scale(1);
        filter: drop-shadow(0 3px 5px rgba(0, 0, 0, 0.08));
    }
    to {
        opacity: 0.96;
        transform: scale(1.055);
        filter: drop-shadow(0 14px 18px rgba(0, 0, 0, 0.2));
    }
}
@keyframes drop-target-pulse {
    0% {
        filter: brightness(1);
        opacity: 0.78;
    }
    to {
        filter: brightness(1.08);
        opacity: 1;
    }
}
@keyframes drop-settle {
    0% {
        transform: scale(0.94);
        opacity: 0.45;
    }
    62% {
        transform: scale(1.035);
        opacity: 1;
    }
    to {
        transform: scale(1);
    }
}
