    font-size: 14px;
}
.w2-card-id span {
    display: block;
    font-size: 10.5px;
    color: #aeaeb2;
    margin-top: 2px;
}
.w2-card-follow {
    flex: none;
    height: 26px;
    padding: 0 12px;
    border-radius: 13px;
    background: #131315;
    color: #fff;
    display: grid;
    place-items: center;
    font-size: 11px;
    font-weight: 600;
}
.w2-card-bio {
    margin: 0;
    font-size: 12px;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.w2-card-stats {
    display: flex;
    gap: 16px;
    font-size: 10.5px;
    color: #8e8e93;
}
.w2-card-stats b {
    color: #131315;
    font-size: 12px;
    margin-right: 3px;
    font-variant-numeric: tabular-nums;
}
.w2-card-long {
    margin: 0;
    padding-top: 8px;
    box-shadow: inset 0 0.5px #ececee;
    font-size: 10.5px;
    line-height: 1.55;
    color: #8e8e93;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.w2-inbox {
    padding: 12px 16px 6px;
    display: flex;
    flex-direction: column;
}
.w2-ib-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2px;
}
.w2-ib-head b {
    font-size: 10.5px;
    font-weight: 600;
}
.w2-ib-row {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 10px;
    position: relative;
    min-height: 0;
}
.w2-ib-row + .w2-ib-row:before {
    content: "";
    position: absolute;
    left: 42px;
    right: 0;
    top: 0;
    height: 0.5px;
    background: #ececee;
}
.w2-ib-row .w2-ava {
    position: relative;
}
.w2-ib-t {
    flex: 1;
    min-width: 0;
    line-height: 1.25;
}
.w2-ib-t b {
    display: block;
    font-size: 12px;
}
.w2-ib-t span {
    display: block;
    font-size: 11px;
    color: #8e8e93;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.w2-ib-row small {
    font-size: 10px;
    color: #aeaeb2;
    font-variant-numeric: tabular-nums;
}
.w2-draft {
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.w2-dr-card {
    flex: 1;
    min-height: 0;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 12px;
    border-radius: 16px;
    box-shadow: inset 0 0 0 0.5px #00000017;
    position: relative;
}
.w2-dr-disc {
    flex: none;
    width: 54px;
    height: 54px;
    border-radius: 50%;
    background: radial-gradient(circle, #fff 0 4px, #cfcfd2 4.5px 9px, #2a2a2a 9.5px 100%);
    box-shadow: 0 0 0 0.5px #0000001a;
}
.w2-dr-disc > img {
    border-radius: 50%;
}
.w2-dr-t {
    min-width: 0;
    line-height: 1.25;
}
.w2-dr-t b {
    display: block;
    font-size: 15px;
}
.w2-dr-t span {
    display: block;
    font-size: 11.5px;
    color: #3a3a3c;
    margin-top: 1px;
}
.w2-dr-t small {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    margin-top: 3px;
    font-size: 10px;
    letter-spacing: 0.06em;
    color: #aeaeb2;
}
.w2-dr-x {
    position: absolute;
    right: 10px;
    top: 10px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #f2f2f4;
    display: grid;
    place-items: center;
    color: #8e8e93;
}
.w2-dr-input {
    flex: none;
    height: 36px;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 4px 0 12px;
    border-radius: 18px;
    background: #f6f6f7;
}
.w2-dr-input p {
    flex: 1;
    min-width: 0;
    margin: 0;
    font-size: 12px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.w2-caret {
    display: inline-block;
    width: 1.5px;
    height: 13px;
    margin-left: 2px;
    vertical-align: -2px;
    background: #131315;
    animation: w2-blink 1s steps(1) infinite;
}
@keyframes w2-blink {
    50% {
        opacity: 0;
    }
}
.w2-dr-send {
    flex: none;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: #131315;
    color: #fff;
    display: grid;
    place-items: center;
}
.litot-desktop .desktop-widget.w2-slot.w2-short {
    height: 150px;
    align-self: start;
}
.w2-dday {
    padding: 16px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}
.w2-dday b {
    font-size: 34px;
    font-weight: 250;
    letter-spacing: -1px;
    font-variant-numeric: tabular-nums;
    line-height: 1;
}
.w2-dday p {
    margin: 0;
    font-size: 11.5px;
    color: #8e8e93;
}
.w2-dd-line {
    display: block;
    height: 2px;
    border-radius: 1px;
    background: #efeff1;
}
.w2-dd-line em {
    display: block;
    height: 100%;
    background: #131315;
    border-radius: 1px;
}
.w2-letter {
    padding: 16px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
}
.w2-letter p {
    margin: 6px 0 0;
    font-size: 11.5px;
    line-height: 22px;
    color: #3a3a3c;
    background: repeating-linear-gradient(180deg, transparent 0 21.5px, #ececee 21.5px 22px);
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
}
.w2-letter small {
    align-self: flex-end;
    font-size: 10px;
    color: #aeaeb2;
    font-style: italic;
}
.w2-trio {
    padding: 12px;
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.w2-trio-tiles {
    flex: 1;
    min-height: 0;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 6px;
}
.w2-trio-tiles .w2-img {
    border-radius: 12px;
    background: #e9e9eb;
}
.w2-trio-tiles .t1 {
    background: #d9d9dc;
}
.w2-trio-tiles .t2 {
    background: #f1f1f2;
}
.w2-trio-t b {
    display: block;
    font-size: 12.5px;
    font-weight: 600;
    letter-spacing: 0.02em;
}
.w2-trio-t p {
    margin: 3px 0 0;
    font-size: 10.5px;
    line-height: 1.55;
    color: #8e8e93;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}
.w2-photo {
    border-radius: 18px;
    background: #f6f6f7;
}
.w2-photo > img {
    border-radius: 18px;
}
.w2-photo-ph {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    color: #b4b4b8;
    background: #f6f6f7 radial-gradient(circle, #e3e3e6 1px, transparent 1.4px) 0 0/12px 12px;
    border-radius: inherit;
}
.w2-photo-ph em {
    font-style: normal;
    font-size: 11px;
    letter-spacing: 0.06em;
}
.litot-desktop .desktop-widget.w2-slot.w2-photo-slot {
    border-radius: 18px;
}
.w2-rz {
    position: absolute;
    z-index: 6;
    width: 26px;
    height: 26px;
    display: grid;
    place-items: center;
    touch-action: none;
}
.w2-rz:after {
    content: "";
    width: 13px;
    height: 13px;
    border-radius: 50%;
    background: #fff;
    box-shadow:
        0 0 0 1px #131315,
        0 0 8px #00000024;
}
.w2-rz.tl {
    left: -13px;
    top: -13px;
}
.w2-rz.tr {
    right: -13px;
    top: -13px;
}
.w2-rz.bl {
    left: -13px;
    bottom: -13px;
}
.w2-rz.br {
    right: -13px;
    bottom: -13px;
}
.w2-rz-chip {
    position: absolute;
    z-index: 6;
    left: 50%;
    bottom: -30px;
    transform: translate(-50%);
    height: 22px;
    padding: 0 10px;
    border-radius: 11px;
    background: #131315;
    color: #fff;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.1em;
    display: grid;
    place-items: center;
    white-space: nowrap;
    pointer-events: none;
}
.litot-desktop.is-editing .desktop-widget.w2-resizing {
    animation: none !important;
    box-shadow:
        0 0 0 1px #131315,
        0 0 24px #00000014;
}
.w2-sheet-mask {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 60;
    background: rgba(0, 0, 0, 0.24);
    display: flex;
    align-items: flex-end;
    animation: w2-fade 0.2s ease both;
}
@keyframes w2-fade {
    0% {
        background: rgba(0, 0, 0, 0);
    }
}
.w2-sheet {
    width: 100%;
    max-height: calc(100% - var(--sat, 0px) - 24px);
    display: flex;
    flex-direction: column;
    border-radius: 28px 28px 0 0;
    background: #fff;
    color: #131315;
    box-shadow: 0 0 30px #0000001f;
    animation: w2-up 0.32s cubic-bezier(0.32, 0.72, 0, 1) both;
}
@keyframes w2-up {
    0% {
        transform: translateY(100%);
    }
}
.w2-grab {
    display: block;
    width: 36px;
    height: 5px;
    border-radius: 3px;
    background: #e0e0e3;
    margin: 8px auto 0;
}
.w2-sheet-h {
    display: grid;
    grid-template-columns: 64px 1fr 64px;
    align-items: center;
    height: 46px;
    padding: 0 var(--sp-5, 20px);
}
.w2-sheet-h b {
    text-align: center;
    font-size: 16px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.w2-sheet-h button {
    font-size: 15px;
    color: #8e8e93;
    justify-self: start;
}
.w2-sheet-h .done {
    justify-self: end;
    color: #131315;
    font-weight: 600;
}
.w2-sheet-body {
    position: relative;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 0 var(--sp-5, 20px) calc(22px + var(--sab, 0px));
}
.w2-prev {
    margin: 2px calc(-1 * var(--sp-5, 20px)) 0;
    padding: 18px var(--sp-5, 20px);
    background: #f6f6f7;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 120px;
}
.w2-sec {
    margin: 18px 4px 6px;
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.16em;
    color: #8e8e93;
}
.w2-grp {
    margin-top: 12px;
    border-radius: 16px;
    background: #f6f6f7;
    padding: 0 14px;
}
.w2-sec + .w2-grp {
    margin-top: 0;
}
.w2-row {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 48px;
    text-align: left;
    color: #131315;
}
.w2-row + .w2-row {
    box-shadow: inset 0 0.5px #00000012;
}
.w2-row > span {
    font-size: 14px;
    color: #3a3a3c;
}
.w2-row .danger,
.w2-grp.danger .w2-row span {
    color: #d1312f;
}
.w2-tg {
    flex: none;
    width: 44px;
    height: 26px;
    border-radius: 13px;
    background: #e3e3e6;
    position: relative;
    transition: background 0.2s;
}
.w2-tg:after {
    content: "";
    position: absolute;
    left: 2px;
    top: 2px;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    background: #fff;
    box-shadow: 0 0 4px #00000026;
    transition: transform 0.2s cubic-bezier(0.32, 0.72, 0, 1);
}
.w2-tg.on {
    background: #131315;
}
.w2-tg.on:after {
    transform: translate(18px);
}
.w2-sws {
    display: flex;
    gap: 7px;
    align-items: center;
}
.w2-sw {
    flex: none;
    width: 22px;
    height: 22px;
    border-radius: 50%;
    box-shadow: inset 0 0 0 0.5px #00000026;
    position: relative;
    overflow: hidden;
}
.w2-sw.on {
    box-shadow:
        0 0 0 2px #f6f6f7,
        0 0 0 3.5px #131315;
}
.w2-sw.clear {
    background: linear-gradient(135deg, #fff 46%, #d1d1d6 47% 53%, #fff 54%);
}
.w2-sw.custom {
    display: grid;
    place-items: center;
    font-size: 11px;
    color: #8e8e93;
    background: #fff;
}
.w2-sw.custom input {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    opacity: 0;
    font-size: 16px;
}
.w2-sw.custom input:focus {
    opacity: 1;
    width: 86px;
    left: auto;
    right: 0;
    background: #fff;
    border-radius: 11px;
    padding: 0 8px;
    font-size: 12px;
    color: #131315;
}
.w2-sw.custom:focus-within {
    overflow: visible;
    width: 86px;
    border-radius: 11px;
}
.w2-slider input {
    flex: 1;
    max-width: 130px;
    accent-color: #131315;
}
.w2-slider em {
    flex: none;
    width: 36px;
    text-align: right;
    font-style: normal;
    font-size: 12px;
    color: #8e8e93;
    font-variant-numeric: tabular-nums;
}
.w2-foot {
    margin: 12px 4px 0;
    font-size: 12px;
    line-height: 1.6;
    color: #8e8e93;
}
.w2-seg {
    display: flex;
    gap: 2px;
    padding: 3px;
    margin-top: 14px;
    border-radius: 999px;
    background: #f2f2f4;
}
.w2-seg button {
    flex: 1;
    height: 30px;
    border-radius: 999px;
    font-size: 12.5px;
    color: #6e6e73;
}
.w2-seg button.on {
    background: #fff;
    color: #131315;
    font-weight: 600;
    box-shadow:
        0 0 0 0.5px #0000000a,
        0 0 8px #0000000f;
}
.w2-icon-demo {
    margin: 4px calc(-1 * var(--sp-5, 20px)) 0;
    padding: 22px 0 18px;
    background: #f6f6f7;
    display: flex;
    justify-content: center;
}
.litot-desktop .desktop-app.ic2 .app-squircle {
    background: var(--ic-bg);
    color: var(--ic-fg);
    box-shadow:
        0 0 0 0.5px #0000000a,
        0 2px 10px #00000012;
}
.litot-desktop .desktop-app.ic2.ic2-flat .app-squircle {
    box-shadow: none;
}
.litot-desktop .desktop-app.ic2.ic2-glass .app-squircle {
    backdrop-filter: blur(var(--ic-blur));
    -webkit-backdrop-filter: blur(var(--ic-blur));
}
.litot-desktop .desktop-app.ic2 .app-label {
    color: var(--ic-lb, inherit);
}
.litot-desktop .desktop-app.ic2.ic2-compact .app-squircle {
    width: calc(var(--desk-icon) - 2px);
    height: calc(var(--desk-icon) - 2px);
}
.litot-desktop .desktop-app.ic2.ic2-compact .app-squircle svg {
    width: 27px;
    height: 27px;
}
.litot-desktop .desktop-app.ic2.ic2-compact .app-label {
    font-size: 10.5px;
    font-weight: 400;
    letter-spacing: 0;
}
.litot-desktop .desktop-app.ic2.ic2-compact .app-launch {
    gap: 7px;
}
.litot-desktop.theme-dark .desktop-app.ic2.ic2-auto .app-squircle {
    background: #2a2a2a;
    color: #f2f2f2;
    box-shadow: 0 0 0 0.5px #ffffff0f;
}
.litot-desktop.theme-dark .desktop-app.ic2.ic2-auto .app-label {
    color: #f2f2f2;
}
.litot-desktop.desk-v3.theme-light .desktop-wallpaper:not(.has-image) {
    background: #fff;
}
.litot-desktop.desk-v3.theme-light .desktop-wallpaper:not(.has-image):after {
    display: none;
}
.litot-desktop.desk-v3.theme-light .desktop-dock {
    background: #f6f6f7;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: inset 0 0 0 0.5px #0000000a;
}
.wl-head {
    position: sticky;
    top: -8px;
    z-index: 3;
    margin: -8px calc(-1 * var(--desk-gut, 20px)) 0;
    padding: 8px 0 12px;
    background: var(--desk-bg);
}
.wl-pills {
    position: relative;
    display: flex;
    gap: 4px;
    overflow-x: auto;
    margin: 0 var(--desk-gut, 20px);
    padding: 4px;
    border-radius: 999px;
    background: rgba(120, 120, 128, 0.1);
    scrollbar-width: none;
}
.wl-pills::-webkit-scrollbar {
    display: none;
}
.wl-pills button {
    flex: none;
    height: 36px;
    padding: 0 6px 0 16px;
    border: 0;
    border-radius: 999px;
    background: none;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 13.5px;
    color: var(--desk-muted);
    transition:
        background 0.25s,
        color 0.2s;
}
.wl-pills button i {
    font-style: normal;
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    border-radius: 999px;
    background: rgba(120, 120, 128, 0.14);
    display: grid;
    place-items: center;
    font-size: 11px;
    font-weight: 600;
    color: var(--desk-muted);
    font-variant-numeric: tabular-nums;
    transition:
        background 0.25s,
        color 0.2s;
}
.wl-pills button.on {
    background: #131315;
    color: #fff;
    font-weight: 600;
}
.wl-pills button.on i {
    background: #fff;
    color: #131315;
}
.theme-dark .wl-pills button.on {
    background: #f2f2f2;
    color: #131315;
}
.theme-dark .wl-pills button.on i {
    background: #131315;
    color: #f2f2f2;
}
.wl-sec {
    margin-top: var(--sp-2, 8px);
}
.wl-h {
    margin: var(--sp-5, 20px) 6px var(--sp-3, 12px);
    font-size: 13px;
    font-weight: 600;
    color: var(--desk-text);
}
.wl-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--sp-3, 12px);
}
.wl-card {
    position: relative;
    min-width: 0;
}
.wl-card.wide {
    grid-column: 1 / -1;
}
.wl-hit {
    width: 100%;
    display: flex;
    flex-direction: column;
    padding: var(--sp-2, 8px);
    border: 0;
    border-radius: 28px;
    background: var(--glass-strong);
    color: inherit;
    text-align: left;
    box-shadow:
        0 0 0 0.5px #0000000a,
        0 0 16px #0000000d;
    transition: transform 0.16s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.wl-hit:active {
    transform: scale(0.975);
}
.wl-stage {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 96px;
    padding: var(--sp-4, 16px) var(--sp-3, 12px);
    border-radius: 22px;
    background: #f6f6f7;
    overflow: hidden;
    pointer-events: none;
}
.theme-dark .wl-stage {
    background: #2a2a2c;
}
.wl-stage .desktop-widget {
    animation: none !important;
}
.wl-stage .desktop-widget.w2-daytile {
    width: 58px !important;
    height: 58px !important;
    margin: 6px auto 0;
}
.wl-stage iframe {
    width: 100%;
    height: 100%;
    border: 0;
    display: block;
}
.wl-meta {
    display: flex;
    align-items: center;
    gap: var(--sp-2, 8px);
    padding: 12px 6px 6px 10px;
}
.wl-t {
    flex: 1;
    min-width: 0;
    line-height: 1.3;
}
.wl-t b {
    display: block;
    font-size: 14px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.wl-t small {
    display: block;
    margin-top: 2px;
    font-size: 11.5px;
    color: var(--desk-muted);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.wl-add {
    flex: none;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: #131315;
    color: #fff;
    display: grid;
