    font-variant-numeric: tabular-nums;
}
.mfr-row-t {
    flex: 1;
    min-width: 0;
    display: grid;
    gap: 1px;
}
.mfr-row-t b {
    font-size: 15px;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mfr-row-t small {
    font-size: 13px;
    color: var(--mu-sub, #8e8e8e);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mfr-more {
    color: #8e8e8e;
}
.mfr-empty {
    padding: 30px 20px;
    text-align: center;
    font-size: 13px;
    line-height: 1.7;
    color: var(--mu-sub, #8e8e8e);
}
.mfr-foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 18px 20px 10px;
    font-size: 12px;
    color: var(--mu-sub, #8e8e8e);
}
.mfr-foot button {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 13px;
    font-weight: 600;
    color: #111;
}
@media (prefers-reduced-motion: reduce) {
    .mfr-btn {
        transition: none;
    }
}
.mfr-cover {
    position: relative;
    display: block;
    flex: none;
    overflow: hidden;
    box-shadow: inset 0 0 0 0.5px #00000014;
    color: #111;
}
.mfr-cover.dark {
    color: #fff;
}
.mfr-cover em {
    position: absolute;
    left: 10%;
    top: 9%;
    font-style: normal;
    font-size: 9px;
    letter-spacing: 0.2em;
    font-weight: 700;
    opacity: 0.6;
}
.mfr-cover b {
    position: absolute;
    left: 10%;
    right: 10%;
    bottom: 9%;
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: -0.01em;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}
.mfr-cell > .mfr-cover {
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 1;
}
.mfr-cell > .mfr-cover b {
    font-size: 13px;
}
.mfr-pcard {
    flex: none;
    width: 138px;
    display: grid;
    justify-items: center;
    gap: 3px;
    padding: 18px 10px 14px;
    border-radius: 16px;
    background: #f6f6f6;
    text-align: center;
    transition: transform 0.12s;
}
.mfr-pcard:active {
    transform: scale(0.97);
}
.mfr-pcard b {
    margin-top: 8px;
    font-size: 14px;
    font-weight: 600;
    max-width: 118px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mfr-pcard small {
    font-size: 11.5px;
    color: var(--mu-sub, #8e8e8e);
    max-width: 118px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.mfr-pbtn {
    margin-top: 10px;
    height: 28px;
    padding: 0 16px;
    border-radius: 14px;
    background: #111;
    color: #fff;
    font-size: 12.5px;
    font-weight: 600;
    display: grid;
    place-items: center;
}
